/******************************************************************************
 * Gallery.
 *****************************************************************************/
define('helpers/gallery',['photoswipe'], function (PhotoSwipe) {
    "use strict";

    /**
     * Initializes the species gallery.
     */
    var Gallery =  function (species) {
        var images = [],
            img = {},
            gallery = species.get('gallery'),
            gallery_authors = species.get('gallery_authors'),
            gallery_sex = species.get('gallery_sex'),
            profile_pic_sex = species.get('profile_pic_sex'),
            profile_pic_author = species.get('profile_pic_author'),
            //CSC
            common_name = species.get('common_name'),
            taxon = species.get('taxon');
           
        //build image array
        //CSC
        //img = image(species.get('profile_pic'), profile_pic_author, profile_pic_sex);
        img = image(species.get('profile_pic'), profile_pic_author, profile_pic_sex, taxon, common_name);
        
        images.push(img);
        for (var i = 0; i < gallery.length; i++) {
            
            //CSC - check for undefined
            //alert (gallery_authors[i] + ' - ' + gallery_sex[i]);
            if (gallery_sex[i] === undefined && typeof gallery_sex[i] === "undefined") {
            	//alert("undefined value detected");
            	gallery_sex[i] = " ";
            }
            
            img = image(gallery[i], gallery_authors[i], gallery_sex[i], taxon, common_name);
            
            images.push(img);
        }

        //CSC
        //function image (url, author, sex) {
        function image (url, author, sex, sname, cname) {
            return {
                url: url,
                caption: cname + ' (' + sname + ') ' + sex + ' Ⓒ ' + author
            };
        }

        return PhotoSwipe.attach(images,
            {
                jQueryMobile: true,
                preventSlideshow: true,
                allowUserZoom: true,
                loop: true,
                captionAndToolbarAutoHideDelay: 0,
                enableMouseWheel: true,
                enableKeyboard: true,

                preventHide: false,
                getImageSource: function(obj){
                    return obj.url;
                },
                getImageCaption: function(obj){
                    return obj.caption;
                }
            }
        );
    };

    return Gallery;
});



/******************************************************************************
 * Species list view used in ListPage view.
 *****************************************************************************/
define('views/list',[
    'backbone',
    'models/species_list_sorts',
    'models/species_list_filters',
    'helpers/gallery',
    'templates'
], function (Backbone, sorts, filters, Gallery) {
    'use strict';

    var View = Backbone.View.extend({
        tagName: 'ul',

        attributes: {
            'data-role': 'listview',
            'class': 'listview-full'
        },

        /**
         * Initializes the species list view.
         */
        initialize: function () {
            _log('views.SpeciesList: initialize', log.DEBUG);

            this.listenTo(this.collection, 'change', this.update);
            this.listenTo(app.models.user, 'change:filters',  this.update);
            this.listenTo(app.models.user, 'change:sort',  this.update);
        },

        /**
         * Renders the species list.
         * @returns {SpeciesListView}
         */
        render: function (callback) {
            _log('views.SpeciesList: render', log.DEBUG);

            var that = this;
            this.prepareList(function (list){
                var container = document.createDocumentFragment(); //optimising the performance

                _.each(list, function (specie) {
                    var listSpeciesView = new SpeciesListItemView({model: specie});
                    container.appendChild(listSpeciesView.render().el);
                });

                that.$el.html(container); //appends to DOM only once

                //attach listeners

                if (callback){
                    callback(that.$el);
                }
            });

            return this;
        },

        update: function () {
            _log('list: updating', log.DEBUG);
            this.render(function($el){
                $el.listview('refresh');
            });
        },

        /**
         * Prepares the species list - filters, sorts.
         */
        prepareList: function (callback) {
            var filtersToApply = _.cloneDeep(app.models.user.get('filters'));
            var sort = app.models.user.get('sort');
            var list = this.collection.models.slice(); //shallow copy of array
            this.prepareListCore(list, sort, filtersToApply, callback);
        },

        /**
         * Prepares the species list. Core functionality.
         *
         * @param list
         * @param sort
         * @param filters
         */
        prepareListCore: function (list, sort, filtersToApply, callback) {
            //todo: might need to move UI functionality to higher grounds
            $.mobile.loading("show");

            var that = this;
            //filter list
            var filterGroups = Object.keys(filtersToApply);
            if (filterGroups.length > 0) {
                var filterGroupID = filterGroups[0];
                var filterGroup = filtersToApply[filterGroupID];
                if (filterGroup.length > 0) {
                    var onFilterGroupSuccess = function (species) {
                        delete filtersToApply[filterGroup];
                        that.prepareListCore(species, sort, filtersToApply, callback);
                        return;
                    };

                    this.filterGroupCore(list, [], filterGroup, filterGroupID, onFilterGroupSuccess);
                    return;
                } else {
                    delete filtersToApply[filterGroupID];
                    that.prepareListCore(list, sort, filtersToApply, callback);
                    return;
                }
            }

            function onSortSuccess() {
                //todo: might need to move UI functionality to higher grounds
                $.mobile.loading("hide");
                if (callback) {
                    callback(list);
                }
            }

            sorts[sort].sort(list, onSortSuccess);
        },

        /**
         * Iterates through the grouped filters applying them to the list.
         *
         * @param list
         * @param filteredList
         * @param filterGroup filters to apply
         * @param filterGroupID
         * @param callback
         */
        filterGroupCore: function (list, filteredList, filterGroup, filterGroupID, callback) {
            if (filterGroup.length > 0) {
                var filterID = filterGroup.pop();
                var filter = filters[filterGroupID].filters[filterID];
                var that = this;

                var onSuccess = function (filteredList) {
                    var uniqueFilteredList = _.uniq(filteredList);
                    that.filterGroupCore(list, uniqueFilteredList, filterGroup, filterGroupID, callback);
                };
                filter.run(list, filteredList, onSuccess);

            } else {
                callback(filteredList);
            }
        },

        /**
         * Returns the roup of the filterID.
         *
         * @param filter
         * @returns {Array}
         */
        getFilterCurrentGroup: function (filterID) {
            //iterate all filter groups
            var group = null;
            _.each(filters, function (groupFilters, groupID) {
                //and filters
                _.each(groupFilters.filters, function (_filter, _filterID) {
                    if(_filterID === filterID) {
                        group = groupID;
                    }
                });
            });

            return group;
        }
    });

    var SpeciesListItemView = Backbone.View.extend({
        tagName: "li",

        template: app.templates.list_item,

        events: {
            'click img': 'showGallery'
        },

        /**
         * Renders the individual list item representing the species.
         *
         * @returns {SpeciesListItemView}
         */
        render: function () {
            this.$el.html(this.template(this.model.attributes));
            return this;
        },

        showGallery: function (e) {
            (new Gallery(this.model)).show(0);
            e.preventDefault();
        }
    });

    return View;
});

/******************************************************************************
 * Species list controls view used in ListPage view.
 *****************************************************************************/
define('views/list_controls',[
    'backbone',
    'models/species_list_sorts',
    'models/species_list_filters',
    'templates'
], function (Backbone, sorts, filters) {
    'use strict';

    var View = Backbone.View.extend({
        tagName: 'div',
        id: 'list-controls-tabs',

        template: app.templates.list_controls,
        template_sort: app.templates.list_controls_sort,
        template_filter: app.templates.list_controls_filter,

        initialize: function (options) {
            options || (options = {});
            this.multi = options.multi;
            this.filtersKey = options.filtersKey || 'filters';
            this.sortKey = options.sortKey || 'sort';
            this.render();
        },

        render: function () {
            this.$el.html(this.template());

            this.renderListSortControls();
            this.renderListFilterControls();
            this.setListControlsListeners();
        },

        attributes: function () {
            return {
                "data-role": 'tabs'
            };
        },

        /**
         * Renders and appends the list sort controls.
         */
        renderListSortControls: function () {
            var keys = Object.keys(sorts);
            for (var i = 0, length = keys.length; i < length; i++) {
                var sort = app.models.user.get(this.sortKey);

                if (keys[i] === sort) {
                    sorts[keys[i]].checked = "checked";
                }
                sorts[keys[i]].multi = this.multi ? "-multi" : "";
            }

            var placeholder = this.$el.find('#list-controls-sort-placeholder');

            placeholder.html(this.template_sort(sorts));
            placeholder.trigger('create');
        },

        /**
         * Renders and appends the list filter controls.
         */
        renderListFilterControls: function () {
            var currentFilters = app.models.user.get(this.filtersKey);

            _.each(filters, function (filterGroup, filterGroupID) {
                _.each(filterGroup.filters, function (filter, filterID) {
                    if (currentFilters[filterGroupID] && currentFilters[filterGroupID].indexOf(filterID) >= 0) {
                        filter.checked = "checked";
                    } else {
                        filter.checked = "";
                    }
                });
            });

            var placeholder = this.$el.find('#list-controls-filter-placeholder');

            placeholder.html(this.template_filter(filters));
            placeholder.trigger('create');
        },

        /**
         * Has to be done once on list creation.
         */
        setListControlsListeners: function () {
            var that = this;
            this.$el.find('.sort').on('change', function () {
                app.models.user.save(that.sortKey, $(this).data('id'));
            });

            this.$el.find('.filter').on('change', function (e) {
                app.models.user.toggleListFilter(this.id, $(this).data('group'), that.multi);
            });
        }
    });

    return View;
});

/******************************************************************************
 * Asks the user to start an appcache download process.
 *****************************************************************************/
define('views/dialog_download',['jquery'], function ($) {
    var Download = function (callback, silent) {
        //for some unknown reason on timeout the popup does not disappear
        setTimeout(function () {
            function onSuccess() {
                app.models.user.set('downloaded-app', true);
                app.models.user.save();

                //Send update to Google Analytics
                //commented off by csc
                /*
                if (app.CONF.GA.STATUS){
                    require(['ga'], function (ga) {
                        if (app.browser.isMobile()){
                            ga('send', 'event', 'app', 'downloadSuccess');
                        } else {
                            ga('send', 'event', 'app', 'downloadDesktopSuccess');
                        }
                    });
                }
                */

                var message =
                    '<center><h3>Download successful, you are ready to go!</h3></center>';

                if (!silent) {
                    app.message(message, 3000);
                }

                callback && callback();
            }

            function onError(error) {
                _log(error, log.ERROR);
                app.message(error);
            }

            startManifestDownload('appcache', onSuccess, onError, silent);
        }, 500);
    };

    /**
     * Starts an Appcache Manifest Downloading.
     *
     * @param id
     * @param files_no
     * @param src
     * @param callback
     * @param onError
     */
    function startManifestDownload (id, callback, onError, silent) {
        /*todo: Add better offline handling:
         If there is a network connection, but it cannot reach any
         Internet, it will carry on loading the page, where it should stop it
         at that point.
         */
        if (navigator.onLine) {
            var src = app.CONF.OFFLINE.APPCACHE_URL;
            var frame = document.getElementById(id);
            if (frame) {
                //update
                frame.contentWindow.applicationCache.update();
            } else {
                var frameHtml = '<iframe id="' + id + '" src="' + src + '" width="215px" height="215px" scrolling="no" frameBorder="0"></iframe>';

                //init
                if (silent) {
                    $('body').append('<div style="display:none">' + frameHtml + '</div>')
                } else {
                    app.message(frameHtml, 0);
                }
                frame = document.getElementById(id);

                //After frame loading set up its controllers/callbacks
                frame.onload = function () {
                    _log('Manifest frame loaded', log.INFO);
                    if (callback != null) {
                        frame.contentWindow.finished = callback;
                    }

                    if (onError != null) {
                        frame.contentWindow.error = onError;
                    }
                }
            }
        } else {
            app.message("<center><h2>Sorry</h2></center><br/><h3>Looks like you are offline!</h3>");
        }
    };

    return Download;
});
/******************************************************************************
 * Functions to work with browser information.
 *
 * Checks if the page is in the home screen (app) mode.
 * Generic function to detect the browser vendor.
 *
 * Note: Chrome has to have and ID of both Chrome and Safari therefore
 * Safari has to have an ID of only Safari and not Chrome
 *****************************************************************************/
define('helpers/browser',[], function () {
    "use strict";
    var ua = navigator.userAgent.toLowerCase();

    var isIPhone = is('iphone');
    var isIPad = is('ipad');
    var isIPod = is('ipad');
    var isChrome = is('chrome') || is('crmo');
    var isFirefox = is('firefox');


    function is (string) {
        return ua.search(string) >= 0;
    }

    var detect = function (browser) {
        browser = browser.toLowerCase();

        "use strict";
        if (browser === 'chrome' || browser === 'safari') {
            var isChrome = is('chrome'),
                isSafari = is("safari");

            if (isSafari) {
                if (browser === 'chrome') {
                    //Chrome
                    return isChrome;
                }
                //Safari
                return !isChrome;
            }
            if (isMobile()) {
                //Safari homescreen Agent has only 'Mobile'
                return true;
            }
            return false;
        }
        return (is(browser));
    };

    var isMobile = function () {
        return is('mobile') || is('android');
    };

    var isIOS = function () {
        return isIPad || isIPod || isIPhone;
    };

    var isAndroidChrome = function () {
        return is('android') && isChrome;
    };

    var getIOSVersion = function () {
        var ver = /i.*OS (\d+)_(\d+)(?:_(\d+))?/i.exec(ua);
        return ver[1];
    };

    var isHomeMode = function () {
        try {
            var iOS = window.navigator.standalone,
                IE = (window.external && window.external.msIsSiteMode && window.external.msIsSiteMode());

            return iOS || IE;
        } catch (err) {
            _log(err, log.ERROR);

            return false;
        }

    };

    return {
        is: is,
        detect: detect,
        isMobile: isMobile,
        isIOS: isIOS,
        isIPhone: isIPhone,
        isAndroidChrome: isAndroidChrome,
        getIOSVersion: getIOSVersion,
        isHomeMode: isHomeMode
    };
});



/******************************************************************************
 * Dialog to show the user how to bookmark the web page to home screen.
 *****************************************************************************/
define('views/dialog_add_homescreen',['jquery', 'helpers/browser'], function ($, browser) {
    var Dialog = function (callback) {
        if(browser.isMobile() && !browser.isHomeMode()) {
            var nextButtonID = 'next-dialog-button',
                message = '';

            if(browser.isIOS()){
                message =
                    '<div class="add-homescreen">' +
                        '<center><h2>Download instructions</h2></center>' +
                        '<ol>' +
                        '<li class="instruction">' +
                            '<img src="images/add_homescreen_1.png">' +
                            '<p>Click <b style="white-space: nowrap;">Sharing button</b></p>' +
                        '</li>' +
                        '<li class="instruction">' +
                            '<img src="images/add_homescreen_2.png">' +
                            '<p>Tap <b style="white-space: nowrap;">Add to home screen</b></p>' +
                        '</li>' +
                        '<li class="instruction">' +
                            '<img id="safari-add-homescreen" src="images/Icon-48.png" style="margin-right: -2px;width: 29px;">' +
                            '<p><b>Open app</b> from home screen.</p>' +
                        '</li>' +
                        '</ol>' +
                    '</div>';

            } else {
                message =
                    '<div class="add-homescreen">' +
                        '<center><h2>Download instructions</h2></center>' +
                        '<ol>' +
                        '<li class="instruction">' +
                            (browser.is('chrome') ? '<img src="images/add_homescreen_1_android.png">' : '') +
                            '<p>Find <strong style="white-space: nowrap;">Browser Menu</strong></p>' +
                        '</li>' +
                        '<li class="instruction">' +
                            '<img src="images/Icon-48.png" style="margin-right: -2px;width: 29px;">' +
                            '<p>Tap <strong style="white-space: nowrap;">Add to Home Screen</strong></p>' +
                        '</li>' +
                        '</ol>' +

                        '<button id="' + nextButtonID + '" style="width:43%; float:right"' +
                        'class="ui-btn ui-btn-inline ui-icon-carat-r ui-btn-icon-right ' +
                        'ui-mini">Next</button>' +
                '</div>';
            }

            app.message(message, 0, true);

            $('#' + nextButtonID).on('click', callback);
        } else {
            callback();
        }

    };

    return Dialog;
});
