/******************************************************************************
 * User model. Persistent.
 *****************************************************************************/
define('models/user',[
    'backbone',
    'helpers/location',
    'backbone.localStorage',
    'conf',
    'latlon'
], function (Backbone, locHelp) {
    'use strict';

    var User = Backbone.Model.extend({
        id: 'user',

        defaults: {
            name: '',
            surname: '',
            email: '',
            secret: '',
            locations: [],
            autosync: true,
            /* CSC - this overrided the default value defined in the scripts/conf.js
            sort: 'common_name',
            sortMulti: 'common_name',
            */
            sort: 'taxonomic',
            sortMulti: 'taxonomic',
            filters: {},
            filtersMulti: {},
            favourites: []
        },

        /**
         * Initializes the user.
         */
        initialize: function () {
            this.fetch();
        },

        localStorage: new Store(app.NAME),

        /**
         * Resets the user login information.
         */
        signOut: function () {
            this.set('email', '');
            this.set('secret', '');
            this.set('name', '');
            this.set('surname', '');
            this.save();
            this.trigger('logout');
        },

        /**
         * Sets the app login state of the user account.
         * Saves the user account details into storage for permanent availability.
         *
         * @param user User object or empty object
         */
        signIn: function (user) {
            this.set('secret', user.secret || '');
            this.setContactDetails(user);
            this.save();
            this.trigger('login');
        },

        /**
         * Sets user contact information.
         */
        setContactDetails: function (user) {
            this.set('email', user.email || '');
            this.set('name', user.name || '');
            this.set('surname', user.surname || '');
            this.save();
        },

        /**
         * Returns user contact information.
         */
        hasSignIn: function () {
            return this.get('secret');
        },

        /**
         * Saves user location.
         *
         * @param location
         */
        setLocation: function (location) {
            var MAX_LENGTH = 10; //max number of locations to store
            var locations = this.get('locations'),
                exists = false;

            //check if exists
            locations.forEach(function (loc) {
                if (loc.latitude === location.latitude && loc.longitude === location.longitude) {
                    exists = true;
                }
            });

            if (!exists) {
                //add
                locations.splice(0, 0, location);
                if (locations.length > MAX_LENGTH) {
                    locations.length = MAX_LENGTH
                }
                this.set('locations', locations);
                this.trigger('change:locations');
                this.save();
            }
        },

        /**
         * Returns user location as Grid Reference.
         *
         * @param geoloc
         * @returns {*}
         */
        getLocationSref: function (location) {
            var LOCATION_GRANULARITY = 2; //Precision of returned grid reference (6 digits = metres).

            location = location || this.get('locations')[0];
            if (!location) {
                return null;
            }

            //get translated location
            var gref = locHelp.coord2grid(location, LOCATION_GRANULARITY);

            //remove the spaces
            return gref.replace(/ /g, '');
        },

        /**
         * Adds/removes favourite species ID from user information.
         *
         * @param speciesID
         */
        toggleFavouriteSpecies: function (speciesID) {
            var favourites = _.clone(this.get('favourites'));  //CLONING problem as discussed:
            //https://stackoverflow.com/questions/9909799/backbone-js-change-not-firing-on-model-change

            if (_.indexOf(favourites, speciesID) >= 0) {
                favourites = _.without(favourites, speciesID);
            } else {
                favourites.push(speciesID);
            }

            this.save('favourites', favourites);
        },

        /**
         * Checks if the speciesID belongs to user favourites.
         *
         * @param speciesID
         * @returns {boolean}
         */
        isFavourite: function (speciesID) {
            var favourites = this.get('favourites');
            return _.indexOf(favourites, speciesID) >= 0;
        },

        /**
         * Adds/removes species list filter from user information.
         *
         * @param filterID
         * @param groupID group the filter belongs to
         * @returns {boolean}
         */
        toggleListFilter: function (filterID, groupID, multi) {
            // var userFilters = _.clone(this.get('filters'));  //CLONING problem as discussed:
            //https://stackoverflow.com/questions/9909799/backbone-js-change-not-firing-on-model-change
            var filtersName = multi ? 'filtersMulti' : 'filters',
                userFilters = this.get(filtersName);

            var exists = false;
            if (userFilters[groupID]) {
                exists = userFilters[groupID].indexOf(filterID) >= 0;
                if (exists) {
                    userFilters[groupID] = _.without(userFilters[groupID], filterID);
                } else {
                    userFilters[groupID].push(filterID);
                }
            } else {
                userFilters[groupID] = [filterID];
            }

            this.set(filtersName, userFilters);
            this.save();
            this.trigger('change:' + filtersName);

            return !exists; //return the state of the filter added/removed
        },

        /**
         * Checks if the filterID belongs to user selected ones.
         *
         * @param filterID
         * @param filters
         * @returns {boolean}
         */
        groupHasListFilter: function (filterID, groupID, filters) {
            filters = filters || this.get('filters');
            return _.indexOf(filters[groupID], filterID) >= 0;
        },

        /**
         * @returns {boolean} Scientific or different type of sorting is selected
         */
        isSortScientific: function (multi) {
            var sort = this.get(multi ? 'sortMulti' : 'sort');
            return sort === 'scientific' || sort === 'scientific_r';
        },

        appendSampleUser: function (sample) {
            sample.set('name', this.get('name') || '_');
            sample.set('surname', this.get('surname'));
            sample.set('email', this.get('email'));

            return sample;
        }
    });

    return User;
});
/******************************************************************************
 * Dialog to get the user contact details.
 *****************************************************************************/
define('views/dialog_user_details',[
    'jquery',
    'jquery.mobile',
    'helpers/validate',
    'models/user'
], function ($, jqm, validate) {
    var ContactDetailsDialog = function (callback) {
        var personalDetailsButtonID = "personal-details-dialog-button";
        var message =
            '<h3>Your details:</h3>' +

            '<input type="text" class="dark-border" name="user-email" placeholder="Email" data-role="none">' +
            '<input type="text" class="dark-border" name="user-name" placeholder="Name" data-role="none">' +
            '<input type="text" class="dark-border" name="user-surname" placeholder="Surname" data-role="none">' +
            '<button id="' + personalDetailsButtonID + '">Sync</button>';

        app.message(message, 0, true);

        var previousEmail = app.models.user.get('email');
        var previousName = app.models.user.get('name');
        var previousSurname = app.models.user.get('surname');
        if (previousEmail && previousName && previousSurname) {
            $('[name="user-email"]').val(previousEmail);
            $('[name="user-name"]').val(previousName);
            $('[name="user-surname"]').val(previousSurname);
        }

        //button listeners
        //send
        $('#' + personalDetailsButtonID).on('click', function () {
            var email = $('[name="user-email"]').val();
            var name = $('[name="user-name"]').val();
            var surname = $('[name="user-surname"]').val();

            if (validateUserDetails(email, name, surname)) {

                app.models.user.setContactDetails({
                    'email': email,
                    'name': name,
                    'surname': surname
                });

                $.mobile.loading('hide');
                callback(email, name, surname);
            }

            function validateUserDetails (email, name, surname) {
                if (!name || !surname) {
                    return false;
                }
                return validate.email(email);
            }
        });

        //email check
        var $inputEmail = $('[name="user-email"] ');
        $inputEmail.focusout(function () {
            var valid = validate.email($(this).val());
            var $inputBox = $('[name="user-email"]');
            if (!valid) {
                $inputBox.addClass('input-error');
            } else {
                $inputBox.removeClass('input-error');
            }
        });
    };

    return ContactDetailsDialog;
});
/******************************************************************************
 * User page view.
 *****************************************************************************/
define('views/p_user',[
    'views/_page',
    'views/dialog_user_details',
    'templates',
    'latlon'
], function (DefaultPage, contactDetailsDialog) {
    'use strict';

    var Page = DefaultPage.extend({
        id: 'user',

        template: app.templates.p_user,

        events: {
            'click #syncAll-button': 'syncAll',
            'click .sync': 'sync',
            'click .delete-button': 'deleteSavedRecord'
        },

        initialize: function () {
            _log('views.UserPage: initialize', log.DEBUG);

            this.model = app.models.user;

            this.render();
            this.appendEventListeners();
        },

        render: function () {
            _log('views.UserPage: render', log.DEBUG);

            this.$el.html(this.template());
            $('body').append($(this.el));

            this.$loginWarning = this.$el.find('#login-warning');
            this.$list = this.$el.find('#samples-list-placeholder');
            this.$heading = this.$el.find('#user_heading');

            this.renderUserControls();
            this.renderList();

            return this;
        },

        renderList: function () {
            var that = this;
            app.recordManager.getAll(function (err, samples) {
                if (err) {
                    app.message(err);
                    return;
                }
                that.listView = new SamplesList({
                    collection: samples
                });
                that.$list.html(that.listView.el);
            });
        },

        /**
         * Renders the user login information.
         */
        renderUserControls: function () {
            if (app.models.user.hasSignIn()) {
                //logged in
                var name = app.models.user.get('name');
                var surname = app.models.user.get('surname');
                this.$heading.html(name + ' ' + surname);
                this.$loginWarning.hide();
            } else {
                //logged out
                this.$heading.html('My Account');
                this.$loginWarning.show();
            }
        },

        appendEventListeners: function () {
            this.appendBackButtonListeners();
            this.listenTo(this.model, 'login logout', this.renderUserControls);
        },

        /**
         * Recursively sends all the saved user records.
         */
        syncAll: function (e) {
            function onSample(sample) {
                app.models.user.appendSampleUser(sample);
            }

            function callback(err) {
                if (err) {
                    app.message(err);
                    return;
                }
                app.message('<h2>All synchronised</h2>');
            }

            if (navigator.onLine) {
                var $button = $(e.currentTarget);

                app.recordManager.on('sync:request', function () {
                    $button.addClass('sync-icon-reload');
                });

                app.recordManager.on('sync:err', function () {
                    $button.removeClass('sync-icon-reload');
                });

                app.recordManager.on('sync:done', function () {
                    $button.removeClass('sync-icon-reload');
                });


                if (app.models.user.hasSignIn()) {
                    app.recordManager.syncAll(onSample, callback);
                } else {
                    contactDetailsDialog(function () {
                        app.recordManager.syncAll(onSample, callback);
                    });
                }
            } else {
                //offline
                app.message("<h2>You are offline</h2>");
            }
        },

        /**
         * Sends the saves user record.
         *
         * @param e Event of an element that contains the ID of the saved record as
         * data attribute.
         */
        sync: function (e) {
            var $button = $(e.currentTarget),
                sampleID = $button.data('id');

            var callback = null;
            if (navigator.onLine) {
                //online
                app.recordManager.get(sampleID, function (err, sample) {
                    callback = function (err) {
                        if (err) {
                            app.message(err);
                            return;
                        }
                    };

                    //one way sync (submit) if user is not signed in
                    if (sample.getSyncStatus() != morel.LOCAL) {
                        return;
                    }

                    if (app.models.user.hasSignIn()) {
                        //append user details
                        app.models.user.appendSampleUser(sample);
                        app.recordManager.sync(sample, callback);
                    } else {
                        contactDetailsDialog(function () {
                            //append user details
                            app.models.user.appendSampleUser(sample);
                            app.recordManager.sync(sample, callback);
                        });
                    }
                });
            } else {
                //offline
                app.message("<h2>You are offline</h2>");
            }
        },

        /**
         * Deletes the saves user record.
         *
         * @param e Event of an element that contains the ID of the saved record as
         * data attribute.
         */
        deleteSavedRecord: function (e) {
            //stop propagation of jqm link
            e.stopPropagation();
            e.preventDefault();

            var recordKey = $(e.currentTarget).data('id');
            app.recordManager.remove(recordKey);
        }
    });

    var SamplesList = Backbone.View.extend({
        template: app.templates.samples_list,

        initialize: function () {
            this.render();
            //update view on collection change
            this.collection.on('reset', this.render, this);
            this.collection.on('update', this.render, this);
        },

        render: function () {
            _log('views.SamplesList: render', log.DEBUG);

            this.$el.html(this.template());
            this.$list = this.$el.find('#samples-list');
            this.renderList();
            this.$list.listview().listview('refresh');
        },

        renderList: function () {
            var that = this;
            this.collection.sort(function (a, b) {
                a = a.get('date').split('/');
                a = new Date(a[2], a[1], a[0]);

                b = b.get('date').split('/');
                b = new Date(b[2], b[1], b[0]);

                return (a<b)-(a>b) ;
            });
            this.collection.each(function (sample) {
                var sampleView = new SamplesListItem({
                    model: sample
                });
                that.$list.append(sampleView.el);
            });
        }
    });

    var SamplesListItem = Backbone.View.extend({
        tagName: "li",

        template: app.templates.samples_list_item,

        initialize: function () {
            this.render();
            this.$syncButton = this.$el.find('.sync');

            this.showSyncStatus();
           // this.model.on('change', this.render, this);
            this.model.on('sync:done', this.showSyncStatus, this);
            this.model.on('sync:error', this.showSyncStatus, this);
            this.model.on('sync:request', this.showSync, this);

        },

        render: function () {
            _log('views.SamplesListItem: render', log.DEBUG);

            var templateData = {};
            templateData.id = this.model.id;
            templateData.date = this.model.get('date');

            if (!this.model.get('recorded_all')) {
                var occurrence = this.model.occurrences.getFirst(),
                    speciesID = occurrence.get('taxon');
                var specie = app.collections.species.find({id: speciesID});
                templateData.common_name = specie ? specie.attributes.common_name : '';

                templateData.img = occurrence.images.getFirst();

                //multi record
            } else {
                templateData.multiRecord = this.model.occurrences.length;
            }

            this.$el.html(this.template(templateData));
            //trigger create
        },

        showSyncStatus: function () {
            if (this.model.getSyncStatus() === morel.SYNCED) {
                //on cloud
                this.$syncButton.removeClass('sync-icon-reload');
                this.$syncButton.removeClass('sync-icon-local');
                this.$syncButton.addClass('sync-icon-cloud');
            } else {
                //local
                this.$syncButton.removeClass('sync-icon-reload');
                this.$syncButton.removeClass('sync-icon-cloud');
                this.$syncButton.addClass('sync-icon-local');
            }
        },

        showSync: function () {
            this.$syncButton.removeClass('sync-icon-local');
            this.$syncButton.removeClass('sync-icon-cloud');
            this.$syncButton.addClass('sync-icon-reload');
        }
    });

    return Page;
});

/******************************************************************************
 * Saved record info page view.
 *****************************************************************************/
define('views/p_record_info',[
    'views/_page',
    'templates',
    'conf'
], function (DefaultPage) {
    'use strict';

    var Page = DefaultPage.extend({
        id: 'record-info',

        template: app.templates.p_record_info,

        events: {
            'click #record-delete-button': 'delete'
        },

        initialize: function () {
            _log('views.RecordInfoPage: initialize', log.DEBUG);

            this.render();
        },

        render: function () {
            _log('views.RecordInfoPage: render', log.DEBUG);

            this.$el.html(this.template());
            $('body').append($(this.el));

            this.$recordInfoPlaceholder = this.$el.find('#record-info-placeholder');

            this.appendBackButtonListeners();
            return this;
        },

        update: function (model) {
            _log('views.RecordInfoPage: update', log.DEBUG);

            this.model = model;

            var location = this.model.get('location');
            location = {
                latitude: parseFloat(location.split(',')[0]),
                longitude: parseFloat(location.split(',')[1])
            };
            var p = new LatLon(location.latitude, location.longitude, LatLon.datum.WGS84);
            var grid = OsGridRef.latLonToOsGrid(p);
            grid = grid.toString();
            //if not in UK
            if (!grid) {
                grid = location.latitude.toFixed(4) + ', ' + location.longitude.toFixed(4);
            }

            var templateData = {
                date: this.model.get('date'),
                location: grid,
                comment: this.model.get('comment'),
                recorded_all: this.model.get('recorded_all'),
                occurrences: []
            };

            this.model.occurrences.each(function (occurrence) {
                var specie = app.collections.species.get(occurrence.get('taxon'));
                var data = $.extend({}, occurrence.attributes);
                data.common_name = specie.get('common_name');
                data.taxon = specie.get('taxon');
                data.img = occurrence.images.getFirst();

                templateData.occurrences.push(data);
            });

            var recordInfoView = new RecordInfoView({model: templateData});
            this.$recordInfoPlaceholder.html(recordInfoView.render().el);
            this.$recordInfoPlaceholder.trigger('create');
        },

        delete: function () {
            var that = this;
            var finishedTrips = app.models.user.get('trips');
            if (finishedTrips.indexOf('record-info') < 0 && this.model.warehouse_id) {
                finishedTrips.push('record-info');
                app.models.user.set('trips', finishedTrips);
                app.models.user.save();

                var okBtnID = 'OK-dialog-button';
                var  message =
                    '<div class="add-homescreen">' +
                    '<center><h2>Note</h2></center>' +
                    '<p>Only the record of the sighting held on your mobile device' +
                    ' will be deleted. The sighting you have already sent will remain' +
                    ' in our database.</p>' +
                    '<button id="' + okBtnID + '">OK</button>' +
                    '</div>';

                app.message(message, 0);

                $('#' + okBtnID).on('click', function () {
                    $.mobile.loading('hide');
                    app.recordManager.remove(that.model);
                    window.history.back();
                });
            } else {
                app.recordManager.remove(this.model);
                window.history.back();
            }
        }
    });


    var RecordInfoView = Backbone.View.extend({
        template: app.templates.record_info,

        /**
         * Renders the species profile.
         *
         * @returns {SpeciesProfile}
         */
        render: function () {
            this.$el.html(this.template(this.model));
            return this;
        }
    });

    return Page;
});

